// Filter to rows sent within the last 7 days, group by company (client proxy),
// and compose the weekly summary message.
var rows = $input.all().map(function(i){ return i.json || {}; }).filter(function(r){ return r && Object.keys(r).length > 0; });
var now = Date.now();
var weekAgo = now - 7 * 24 * 60 * 60 * 1000;
function ts(r){
  var d = r.processed_at || r.date_added;
  var p = d ? Date.parse(d) : NaN;
  return isNaN(p) ? null : p;
}
var recent = rows.filter(function(r){ var t = ts(r); return t !== null && t >= weekAgo && t <= now; });
// If no timestamps parse (older test data), fall back to all sent rows so the report still fires.
if (!recent.length && rows.length) { recent = rows; }
var count = recent.length;
// Group by company (client proxy until client_id exists).
var groups = {};
recent.forEach(function(r){
  var company = (r.company && String(r.company).trim()) ? String(r.company).trim() : 'Unknown';
  if (!groups[company]) groups[company] = { company: company, count: 0, bestFit: -1, bestJob: '' };
  groups[company].count++;
  var fit = r.fit_score;
  if (fit === undefined || fit === null || String(fit).trim() === '') fit = r.adjusted_fit_score;
  var fitNum = parseFloat(fit);
  if (!isNaN(fitNum) && fitNum > groups[company].bestFit) { groups[company].bestFit = fitNum; groups[company].bestJob = (r.job_title && String(r.job_title).trim()) ? String(r.job_title).trim() : 'a role'; }
});
// Rank individual applications by fit for the Top 3 list.
var ranked = recent.map(function(r){
  var fit = r.fit_score;
  if (fit === undefined || fit === null || String(fit).trim() === '') fit = r.adjusted_fit_score;
  var fitNum = parseFloat(fit);
  return { job: (r.job_title && String(r.job_title).trim()) ? String(r.job_title).trim() : 'a role', company: (r.company && String(r.company).trim()) ? String(r.company).trim() : 'Unknown', fit: isNaN(fitNum) ? null : fitNum };
}).sort(function(a, b){ return (b.fit === null ? -1 : b.fit) - (a.fit === null ? -1 : a.fit); });
var top3 = ranked.slice(0, 3);
var parts = [];
for (var i = 0; i < top3.length; i++) {
  var t = top3[i];
  var fitStr = (t.fit === null) ? 'N/A' : t.fit;
  parts.push((i + 1) + '. ' + t.job + ' at ' + t.company + ' (' + fitStr + '%)');
}
var topLine = parts.length ? ('Top 3 matches: ' + parts.join(', ')) : 'No matches to highlight this week.';
var message = '\uD83D\uDCCA Weekly Report: Sent ' + count + ' applications this week. ' + topLine;
return [{ json: { message: message, chat_id: '8890901423', total_sent: count, groups: Object.keys(groups).map(function(k){ return groups[k]; }) } }];
